recognize/index.js:
```js
const cloud = require('wx-server-sdk');
cloud.init({ env: cloud.DYNAMIC_CURRENT_ENV });
const { getProvider } = require('./providers');
const { getLevel } = require('./levels');

exports.main = async (event) => {
  try {
    const { fileID, level } = event || {};
    if (!fileID || typeof fileID !== 'string') {
      return fail('INVALID_ARGUMENT', 'fileID is required');
    }
    const lv = getLevel(level);
    const res = await cloud.downloadFile({ fileID });
    const provider = getProvider();
    const result = await provider.recognize(res.fileContent, { level: lv.id, levelConfig: lv });
    return ok({ words: result.words });
  } catch (e) {
    return fail('RECOGNIZE_FAILED', e.message);
  }
};
```

