utils/speech.js:
```js
let plugin = null;
try {
  plugin = requirePlugin('WechatSI');
} catch (e) {
  plugin = null;
}

function speak(text, options) {
  const opts = options || {};
  return new Promise((resolve, reject) => {
    if (!plugin || !plugin.textToSpeech) {
      reject(new Error('WechatSI plugin unavailable'));
      return;
    }
    if (!text) { reject(new Error('empty text')); return; }
    plugin.textToSpeech({
      lang: opts.lang || 'en_US',
      tts: true,
      content: text,
      success: (res) => {
        if (!res || !res.filename) { reject(new Error('no audio file')); return; }
        play(res.filename);
        resolve(res.filename);
      },
      fail: (err) => reject(new Error((err && err.msg) || 'tts failed')),
    });
  });
}
```

