const fs = require('fs');
const path = require('path');

const src = path.resolve(__dirname, '../miniprogram/common/levels.js');
const targets = ['recognize', 'compose'].map((fn) =>
  path.resolve(__dirname, `../cloudfunctions/${fn}/levels.js`)
);

const content = fs.readFileSync(src, 'utf8');
targets.forEach((dest) => {
  fs.writeFileSync(dest, content);
  console.log(`synced -> ${path.relative(process.cwd(), dest)}`);
});
```

