mock.js:
```js
const DICT = {
  cat: '猫',
  dog: '狗',
  cup: '杯子',
  book: '书',
  apple: '苹果',
  tree: '树',
  car: '汽车',
  chair: '椅子',
  window: '窗户',
  table: '桌子',
  phone: '手机',
  flower: '花',
};

const WORDS_BY_LEVEL = {
  primary: ['cat', 'dog', 'cup', 'apple'],
  junior: ['book', 'tree', 'car', 'chair'],
  senior: ['window', 'table', 'phone', 'flower'],
};

function recognize(imageBuffer, opts) {
  const level = (opts && opts.level) || 'primary';
  const words = (WORDS_BY_LEVEL[level] || WORDS_BY_LEVEL.primary).map((w, i) => ({
    word: w,
    translation: DICT[w],
    confidence: Number((0.95 - i * 0.05).toFixed(2)),
    level,
  }));
  return Promise.resolve({ words });
}

function compose(words, opts) {
  const level = (opts && opts.level) || 'primary';
  const picked = (words || []).filter(Boolean).slice(0, level === 'primary' ? 2 : 3);
  if (picked.length < 2) throw new Error('至少需要 2 个单词');
  let sentence;
  if (level === 'primary') {
    sentence = `I can see a ${picked[0]} and a ${picked[1]}.`;
  } else if (level === 'junior') {
    sentence = `There is a ${picked[0]}, a ${picked[1]}, and a ${picked[2] || picked[0]} in the picture.`;
  } else {
    sentence = `Looking at the picture, I notice a ${picked[0]}, a ${picked[1]}, and a ${picked[2] || picked[0]}, which makes the scene lively.`;
  }
  return Promise.resolve({
    sentence,
    translation: '',
    usedWords: picked,
  });
}

module.exports = { recognize, compose };
```

