```js
const app = getApp();
const cloudApi = require('../../utils/cloud');
const speech = require('../../utils/speech');

function decodeText(v) {
  return v ? decodeURIComponent(v) : '';
}

function decodeWords(v) {
  if (!v) return [];
  return decodeURIComponent(v)
    .split('|')
    .map((pair) => {
      const [word, translation] = pair.split('~');
      return { word: word || '', translation: translation || '' };
    })
    .filter((item) => item.word);
}

Page({
  data: {
    level: 'primary',
    words: [],
    sentence: '',
    translation: '',
    usedWords: [],
    generating: false,
    error: '',
  },

  onLoad(options) {
    const opts = options || {};
    const level = opts.level || app.globalData.level || 'primary';
    const words = decodeWords(opts.words);
    if (words.length) {
      this.setData({
        level,
        words,
        sentence: decodeText(opts.sentence),
      });
      return;
    }
    const pending = wx.getStorageSync('pendingResult');
    if (pending && pending.words && pending.words.length) {
      this.setData({
        level: pending.level || level,
        words: pending.words,
        sentence: pending.sentence || '',
        translation: pending.translation || '',
      });
    }
  },

  generateSentence() {
    if (this.data.generating) return;
    const words = this.data.words.map((item) => item.word);
    if (!words.length) return;
    this.setData({ generating: true, error: '' });
    cloudApi
      .compose(words, this.data.level)
      .then((data) => {
        this.setData({
          sentence: data.sentence || '',
          translation: data.translation || '',
          usedWords: data.usedWords || [],
          generating: false,
        });
      })
      .catch((err) => {
        this.setData({ generating: false, error: err.message || '组句失败，请重试' });
      });
  },

  playSentence() {
    const text = this.data.sentence;
    if (!text) return;
    wx.showLoading({ title: '合成中', mask: true });
    speech
      .speak(text)
      .then(() => wx.hideLoading())
      .catch((err) => {
        wx.hideLoading();
        wx.showToast({ title: err.message || '语音合成失败', icon: 'none' });
      });
  },

  onShareAppMessage() {
    const { words, sentence, level } = this.data;
    const encodedWords = words
      .map((item) => `${item.word}~${item.translation || ''}`)
      .join('|');
    const query = [
      `level=${level}`,
      `words=${encodeURIComponent(encodedWords)}`,
      sentence ? `sentence=${encodeURIComponent(sentence)}` : '',
    ]
      .filter(Boolean)
      .join('&');
    return {
      title: sentence || '看图学英语',
      path: `/pages/result/result?${query}`,
    };
  },
});
```

