const { getProvider } = require('./providers');
const { getLevel } = require('./levels');

function ok(data) { return { ok: true, data }; }
function fail(code, message) { return { ok: false, error: { code, message } }; }

exports.main = async (event) => {
  const { words, level } = event || {};
  if (!Array.isArray(words) || words.filter(Boolean).length < 2) {
    return fail('INVALID_ARGUMENT', '至少需要 2 个单词');
  }
  try {
    const levelConfig = getLevel(level);
    const clean = words.filter((w) => typeof w === 'string' && w.trim()).map((w) => w.trim());
    const provider = getProvider();
    const result = await provider.compose(clean, { level: levelConfig.id, levelConfig });
    return ok({
      sentence: result.sentence,
      translation: result.translation || '',
      usedWords: result.usedWords || [],
    });
  } catch (err) {
    return fail('COMPOSE_FAILED', err.message || '组句失败');
  }
};
```

