function call(name, data) {
  return wx.cloud
    .callFunction({ name, data })
    .then((res) => {
      const result = res && res.result;
      if (!result || !result.ok) {
        const message = (result && result.error && result.error.message) || '云函数调用失败';
        throw new Error(message);
      }
      return result.data;
    });
}

function recognize(fileID, level) {
  return call('recognize', { fileID, level });
}

function compose(words, level) {
  return call('compose', { words, level });
}

module.exports = {
  call,
  recognize,
  compose,
};

let plugin = null;
try {
  plugin = requirePlugin('WechatSI');
} catch (err) {
  plugin = null;
}

let audioContext = null;

function getAudioContext() {
  if (!audioContext) {
    audioContext = wx.createInnerAudioContext();
  }
  return audioContext;
}

function play(filePath) {
  const context = getAudioContext();
  context.stop();
  context.src = filePath;
  context.play();
}

function speak(text, options) {
  const opts = options || {};
  return new Promise((resolve, reject) => {
    if (!text) {
      reject(new Error('文本为空'));
      return;
    }
    if (!plugin || !plugin.textToSpeech) {
      reject(new Error('未启用微信同声传译插件'));
      return;
    }
    plugin.textToSpeech({
      lang: opts.lang || 'en_US',
      tts: true,
      content: text,
      success: (res) => {
        if (!res || !res.filename) {
          reject(new Error('语音合成失败'));
          return;
        }
        play(res.filename);
        resolve(res.filename);
      },
      fail: (err) => {
        reject(new Error((err && err.msg) || '语音合成失败'));
      },
    });
  });
}

function stop() {
  if (audioContext) {
    audioContext.stop();
  }
}

module.exports = {
  speak,
  stop,
};

