input.content:
let plugin;
let pluginLoaded = false;
let audioContext = null;

function getPlugin() {
  if (pluginLoaded) {
    return plugin;
  }
  pluginLoaded = true;
  try {
    plugin = requirePlugin('WechatSI');
  } catch (err) {
    plugin = null;
  }
  return plugin;
}

function getAudioContext() {
  if (!audioContext) {
    audioContext = wx.createInnerAudioContext();
  }
  return audioContext;
}

function play(filePath) {
  const context = getAudioContext();
  context.stop();
  context.src = filePath;
  context.play();
}

function speak(text, options) {
  const opts = options || {};
  return new Promise((resolve, reject) => {
    if (!text) {
      reject(new Error('文本为空'));
      return;
    }
    const si = getPlugin();
    if (!si || !si.textToSpeech) {
      reject(new Error('未启用微信同声传译插件'));
      return;
    }
    si.textToSpeech({
      lang: opts.lang || 'en_US',
      tts: true,
      content: text,
      success: (res) => {
        if (!res || !res.filename) {
          reject(new Error('语音合成失败'));
          return;
        }
        play(res.filename);
        resolve(res.filename);
      },
      fail: (err) => {
        reject(new Error((err && err.msg) || '语音合成失败'));
      },
    });
  });
}

function stop() {
  if (audioContext) {
    audioContext.stop();
  }
}

module.exports = {
  speak,
  stop,
};

