const https = require('https');

const LEVEL_NAMES = {
  primary: '小学',
  junior: '初中',
  senior: '高中',
};

function getConfig() {
  const apiKey = process.env.TOKENHUB_API_KEY;
  if (!apiKey) {
    throw new Error('缺少 TOKENHUB_API_KEY');
  }
  return {
    apiKey,
    baseUrl: (process.env.TOKENHUB_BASE_URL || 'https://tokenhub.tencentmaas.com/v1').replace(/\/+$/, ''),
    model: process.env.TOKENHUB_VISION_MODEL || 'hy-vision-2.0-instruct',
  };
}

function postJson(url, headers, body, timeoutMs) {
  return new Promise((resolve, reject) => {
    const target = new URL(url);
    const payload = JSON.stringify(body);
    const request = https.request(
      {
        hostname: target.hostname,
        port: target.port || 443,
        path: `${target.pathname}${target.search}`,
        method: 'POST',
        headers: Object.assign(
          {
            'Content-Type': 'application/json',
            'Content-Length': Buffer.byteLength(payload),
          },
          headers
        ),
      },
      (response) => {
        let data = '';
        response.setEncoding('utf8');
        response.on('data', (chunk) => {
          data += chunk;
        });
        response.on('end', () => {
          let parsed = null;
          try {
            parsed = JSON.parse(data);
          } catch (err) {
            parsed = null;
          }
          if (response.statusCode >= 200 && response.statusCode < 300) {
            resolve(parsed);
            return;
          }
          const error = parsed && parsed.error;
          const message =
            (error && (error.message || error.code)) ||
            (parsed && parsed.message) ||
            data.slice(0, 200);
          reject(new Error(`TokenHub ${response.statusCode}: ${message}`));
        });
      }
    );

    request.on('error', reject);
    request.setTimeout(timeoutMs || 15000, () => {
      request.destroy(new Error('TokenHub 请求超时'));
    });
    request.write(payload);
    request.end();
  });
}

function detectMimeType(buffer) {
  if (buffer.length >= 3 && buffer[0] === 0xff && buffer[1] === 0xd8 && buffer[2] === 0xff) {
    return 'image/jpeg';
  }
  if (
    buffer.length >= 8 &&
    buffer[0] === 0x89 &&
    buffer[1] === 0x50 &&
    buffer[2] === 0x4e &&
    buffer[3] === 0x47
  ) {
    return 'image/png';
  }
  if (
    buffer.length >= 12 &&
    buffer.toString('ascii', 0, 4) === 'RIFF' &&
    buffer.toString('ascii', 8, 12) === 'WEBP'
  ) {
    return 'image/webp';
  }
  if (buffer.length >= 3 && buffer.toString('ascii', 0, 3) === 'GIF') {
    return 'image/gif';
  }
  return 'image/jpeg';
}

function buildPrompt(levelConfig) {
  const levelName = LEVEL_NAMES[levelConfig.id] || '小学';
  return [
    '你是一位英语老师，请识别图片中清晰、可辨认的物体，并给出适合 K12 学生的英文单词。',
    `目标难度：${levelName}。`,
    `返回 ${levelConfig.minWords} 到 ${levelConfig.maxWords} 个物体。`,
    '要求：',
    '1. 每个单词必须是常见、可教学的英文名词或名词短语；',
    '2. 给出简洁准确的中文释义；',
    '3. confidence 为 0 到 1 之间的数字；',
    '4. 只输出 JSON 数组，不要输出解释或 Markdown 代码块。',
    '格式示例：[{"word":"cat","translation":"猫","confidence":0.98}]',
  ].join('\n');
}

function stripCodeFence(text) {
  return String(text || '')
    .replace(/```json/gi, '')
    .replace(/```/g, '')
    .trim();
}

function normalizeWords(content, levelConfig) {
  let parsed;
  try {
    parsed = JSON.parse(stripCodeFence(content));
  } catch (err) {
    throw new Error('识别结果不是合法 JSON');
  }

  const list = Array.isArray(parsed) ? parsed : parsed && parsed.words;
  if (!Array.isArray(list)) {
    throw new Error('识别结果缺少单词列表');
  }

  const seen = {};
  const words = [];
  list.forEach((item) => {
    if (!item || typeof item.word !== 'string') {
      return;
    }
    const word = item.word.trim();
    const key = word.toLowerCase();
    if (!word || seen[key]) {
      return;
    }
    seen[key] = true;
    words.push({
      word,
      translation: typeof item.translation === 'string' ? item.translation.trim() : '',
      confidence: typeof item.confidence === 'number' ? item.confidence : 0.8,
      level: levelConfig.id,
    });
  });

  if (!words.length) {
    throw new Error('没有识别到可用单词');
  }
  return words.slice(0, levelConfig.maxWords || 8);
}

async function recognize(imageBuffer, opts) {
  const levelConfig =
    (opts && opts.levelConfig) || { id: 'primary', minWords: 2, maxWords: 8 };
  if (!Buffer.isBuffer(imageBuffer) || !imageBuffer.length) {
    throw new Error('图片内容为空');
  }

  const config = getConfig();
  const mimeType = detectMimeType(imageBuffer);
  const dataUrl = `data:${mimeType};base64,${imageBuffer.toString('base64')}`;

  const response = await postJson(
    `${config.baseUrl}/chat/completions`,
    { Authorization: `Bearer ${config.apiKey}` },
    {
      model: config.model,
      messages: [
        {
          role: 'user',
          content: [
            { type: 'image_url', image_url: { url: dataUrl } },
            { type: 'text', text: buildPrompt(levelConfig) },
          ],
        },
      ],
      stream: false,
    },
    15000
  );

  const choice = response && response.choices && response.choices[0];
  if (!choice || !choice.message) {
    throw new Error('TokenHub 未返回识别结果');
  }
  if (choice.finish_reason === 'content_filter') {
    throw new Error('图片内容未通过安全审核');
  }

  return { words: normalizeWords(choice.message.content, levelConfig) };
}

module.exports = { recognize };

