function buildPrompt(words, levelConfig) {
  const levelName = LEVEL_NAMES[levelConfig.id] || '小学';
  return [
    '你是一位英语老师，请用给定的英文单词组成一句自然、语法正确的英文句子。',
    `目标难度：${levelName}。`,
    `必须使用至少 ${levelConfig.minWords} 个给定单词；句子总词数不超过 ${levelConfig.maxWords}。`,
    `给定单词：${words.join(', ')}。`,
    '要求：',
    '1. 句子符合该年龄段学生的英语水平；',
    '2. 提供准确的中文翻译；',
