const https = require('https');

function getConfig() {
  const apiKey = process.env.TOKENHUB_API_KEY;
  if (!apiKey) {
    throw new Error('缺少 TOKENHUB_API_KEY');
  }
  return {
    apiKey,
    baseUrl: (process.env.TOKENHUB_BASE_URL || 'https://tokenhub.tencentmaas.com/v1').replace(/\/+$/, ''),
    model: process.env.TOKENHUB_TTS_MODEL || 'minimax-speech-2.8-turbo',
    voice: process.env.TOKENHUB_TTS_VOICE || 'minimax_55e81114-ce7e-4ca1',
    speed: Number(process.env.TOKENHUB_TTS_SPEED || 1),
  };
}

function postJson(url, headers, body, timeoutMs) {
  return new Promise((resolve, reject) => {
    const target = new URL(url);
    const payload = JSON.stringify(body);
    const request = https.request(
      {
        hostname: target.hostname,
        port: target.port || 443,
        path: `${target.pathname}${target.search}`,
        method: 'POST',
        headers: Object.assign(
          {
            'Content-Type': 'application/json',
            'Content-Length': Buffer.byteLength(payload),
          },
          headers
        ),
      },
      (response) => {
        let data = '';
        response.setEncoding('utf8');
        response.on('data', (chunk) => {
          data += chunk;
        });
        response.on('end', () => {
          let parsed = null;
          try {
            parsed = JSON.parse(data);
          } catch (err) {
            parsed = null;
          }
          if (response.statusCode >= 200 && response.statusCode < 300) {
            resolve(parsed);
            return;
          }
          const error = parsed && parsed.error;
          const message =
            (error && (error.message || error.code)) ||
            (parsed && parsed.message) ||
            data.slice(0, 200);
          reject(new Error(`TokenHub ${response.statusCode}: ${message}`));
        });
      }
    );

    request.on('error', reject);
    request.setTimeout(timeoutMs || 15000, () => {
      request.destroy(new Error('TokenHub 请求超时'));
    });
    request.write(payload);
    request.end();
  });
}

async function synthesize(text, opts) {
  if (!text || typeof text !== 'string') {
    throw new Error('文本为空');
  }

  const config = getConfig();
  const voiceId = (opts && opts.voice) || config.voice;

  const response = await postJson(
    `${config.baseUrl}/wand/minimax-tts/sync_tts`,
    { Authorization: `Bearer ${config.apiKey}` },
    {
      model: config.model,
      text,
      voice_setting: {
        voice_id: voiceId,
        speed: config.speed,
        vol: 1,
        pitch: 0,
      },
      audio_setting: {
        sample_rate: 32000,
        bitrate: 128000,
        format: 'mp3',
        channel: 1,
      },
      subtitle_enable: false,
      output_format: 'hex',
    },
    15000
  );

  const baseResp = response && response.base_resp;
  if (baseResp && baseResp.status_code !== 0) {
    throw new Error(`TokenHub TTS ${baseResp.status_code}: ${baseResp.status_msg || '合成失败'}`);
  }

  const audioHex = response && response.data && response.data.audio;
  if (!audioHex) {
    throw new Error('TokenHub TTS 未返回音频');
  }

  const buffer = Buffer.from(audioHex, 'hex');
  if (!buffer.length) {
    throw new Error('TokenHub TTS 音频为空');
  }

  const extra = response.extra_info || {};
  return {
    audioBase64: buffer.toString('base64'),
    mime: 'audio/mpeg',
    size: buffer.length,
    durationMs: typeof extra.audio_length === 'number' ? extra.audio_length : 0,
  };
}

module.exports = { synthesize };

const tokenhub = require('./tokenhub');

function getProvider() {
  return tokenhub;
}

module.exports = { getProvider };

const { getProvider } = require('./providers');

function ok(data) {
  return { ok: true, data };
}

function fail(code, message) {
  return { ok: false, error: { code, message } };
}

exports.main = async (event) => {
  const { text, voice } = event || {};

  if (typeof text !== 'string' || !text.trim()) {
    return fail('INVALID_ARGUMENT', '缺少文本');
  }

  const content = text.trim();
  if (content.length > 500) {
    return fail('INVALID_ARGUMENT', '文本过长');
  }

  try {
    const provider = getProvider();
    const result = await provider.synthesize(content, { voice });
    return ok(result);
  } catch (err) {
    return fail('TTS_FAILED', (err && err.message) || '语音合成失败');
  }
};

{
  "name": "tts",
  "version": "1.0.0",
  "description": "语音合成云函数（TokenHub MiniMax）",
  "main": "index.js",
  "dependencies": {}
}

let audioContext = null;

function hashText(text) {
  let hash = 5381;
  for (let i = 0; i < text.length; i += 1) {
    hash = (((hash << 5) + hash) + text.charCodeAt(i)) >>> 0;
  }
  return hash.toString(16);
}

function getAudioContext() {
  if (!audioContext) {
    audioContext = wx.createInnerAudioContext();
    audioContext.onError((err) => {
      console.error('音频播放失败', err);
    });
  }
  return audioContext;
}

function play(filePath) {
  const context = getAudioContext();
  context.stop();
  context.src = filePath;
  context.play();
}

function ensureAudioFile(text, audioBase64) {
  const fs = wx.getFileSystemManager();
  const filePath = `${wx.env.USER_DATA_PATH}/tts-${hashText(text)}.mp3`;
  try {
    fs.accessSync(filePath);
  } catch (err) {
    fs.writeFileSync(filePath, audioBase64, 'base64');
  }
  return filePath;
}

function speak(text, options) {
  const opts = options || {};
  return new Promise((resolve, reject) => {
    if (!text) {
      reject(new Error('文本为空'));
      return;
    }
    if (!wx.cloud) {
      reject(new Error('云开发未初始化'));
      return;
    }

    const data = { text };
    if (opts.voice) {
      data.voice = opts.voice;
    }

    wx.cloud
      .callFunction({ name: 'tts', data })
      .then((res) => {
        const result = res && res.result;
        if (!result || !result.ok) {
          const message = (result && result.error && result.error.message) || '语音合成失败';
          throw new Error(message);
        }
        const audio = result.data || {};
        if (!audio.audioBase64) {
          throw new Error('语音数据为空');
        }
        const filePath = ensureAudioFile(text, audio.audioBase64);
        play(filePath);
        resolve(filePath);
      })
      .catch((err) => {
        reject(new Error((err && (err.message || err.errMsg)) || '语音合成失败'));
      });
  });
}

function stop() {
  if (audioContext) {
    audioContext.stop();
  }
}

module.exports = {
  speak,
  stop,
};

