parts.text:
Now run the full chain in one evaluate. The base64 is ~2100 chars. The evaluate command will be long but fine.

Function:
```js
function(){
  globalThis.__chain = 'pending';
  var b64 = "...";
  var fs = wx.getFileSystemManager();
  var p = wx.env.USER_DATA_PATH + '/shapes256.png';
  fs.writeFileSync(p, b64, 'base64');
  var words = null;
  wx.cloud.uploadFile({cloudPath:'test/shapes256.png', filePath:p})
    .then(function(up){ return wx.cloud.callFunction({name:'recognize', data:{fileID: up.fileID, level:'primary'}}); })
    .then(function(r){
      var res = r.result;
      if(!res || !res.ok) throw new Error('recognize: ' + JSON.stringify(res));
      words = (res.data.words || []).map(function(w){ return w.word; });
      globalThis.__chainWords = words.join(',');
      return wx.cloud.callFunction({name:'compose', data:{words: words, level:'primary'}});
    })
    .then(function(r){
      var res = r.result;
      if(!res || !res.ok) throw new Error('compose: ' + JSON.stringify(res));
      var sentence = res.data.sentence;
      globalThis.__chainSentence = sentence;
      return wx.cloud.callFunction({name:'tts', data:{text: sentence}});
    })
    .then(function(r){
      var res = r.result;
      if(!res || !res.ok) throw new Error('tts: ' + JSON.stringify(res));
      var audioPath = wx.env.USER_DATA_PATH + '/chain.mp3';
      fs.writeFileSync(audioPath, res.data.audioBase64, 'base64');
      var ctx = wx.createInnerAudioContext();
      ctx.src = audioPath;
      ctx.onEnded(function(){ globalThis.__chain = 'ended'; });
      ctx.onError(function(e){ globalThis.__chain = 'audio error: ' + JSON.stringify(e); });
      ctx.play();
      globalThis.__chain = 'playing';
    })
    .catch(function(e){ globalThis.__chain = 'ERROR: ' + (e.message || e.errMsg); });
  return 'fired';
}
```
Poll `__chain`, `__chainWords`, `__chainSentence`.

Note: if recognize returns only 1 word, compose fails with "至少需要 2 个单词". The image has two objects; likely returns square/circle/red/blue. If not, we'll see.

