Let me implement text wrapping:

```js
function wrapText(ctx, text, maxWidth) {
  const content = String(text || '').trim();
  if (!content) return [];
  // If contains spaces, wrap by words; else by characters.
  if (content.indexOf(' ') !== -1) {
    const words = content.split(/\s+/);
    const lines = [];
    let line = '';
    words.forEach((word) => {
      const test = line ? `${line} ${word}` : word;
      if (ctx.measureText(test).width <= maxWidth) {
        line = test;
      } else {
        if (line) lines.push(line);
        // If a single word is too long, break by characters.
        if (ctx.measureText(word).width > maxWidth) {
          let chunk = '';
          for (let i = 0; i < word.length; i++) {
            const testChunk = chunk + word[i];
            if (ctx.measureText(testChunk).width <= maxWidth) {
              chunk = testChunk;
            } else {
              if (chunk) lines.push(chunk);
              chunk = word[i];
            }
          }
          line = chunk;
        } else {
          line = word;
        }
      }
    });
    if (line) lines.push(line);
    return lines;
  }
  // Chinese / no spaces: break by characters.
  const lines = [];
  let line = '';
  for (let i = 0; i < content.length; i++) {
    const test = line + content[i];
    if (ctx.measureText(test).width <= maxWidth) {
      line = test;
    } else {
      if (line) lines.push(line);
      line = content[i];
    }
  }
  if (line) lines.push(line);
  return lines;
}
```

Then `drawTextBlock`:
```js
function drawTextBlock(ctx, text, opts) {
  const { x, y, maxWidth, font, color, lineHeight, maxLines } = opts;
  ctx.font = font;
  ctx.fillStyle = color;
  ctx.textAlign = 'left';
  ctx.textBaseline = 'top';
  let lines = wrapText(ctx, text, maxWidth);
  if (maxLines && lines.length > maxLines) {
    lines = lines.slice(0, maxLines);
    let last = lines[lines.length - 1];
    while (last.length > 0 && ctx.measureText(`${last}…`).width > maxWidth) {
      last = last.slice(0, -1);
    }
    lines[lines.length - 1] = `${last}…`;
  }
  lines.forEach((line, index) => {
    ctx.fillText(line, x, y + index * lineHeight);
  });
  return y + lines.length * lineHeight;
}
```

`drawLabels`:
```js
function drawLabels(ctx, words, rect) {
  ctx.textAlign = 'left';
  ctx.textBaseline = 'middle';
  words.forEach((item) => {
    if (!item.bbox) return;
    const b = item.bbox;
    const x = rect.x + b.x * rect.w;
    const y = rect.y + b.y * rect.h;
    const w = b.w * rect.w;
    const h = b.h * rect.h;
    ctx.strokeStyle = '#07c160';
    ctx.lineWidth = 4;
    roundRectPath(ctx, x, y, w, h, 10);
    ctx.stroke();

    ctx.font = 'bold 26px sans-serif';
    const label = item.word;
    const textW = ctx.measureText(label).width;
    const labelH = 38;
    const labelW = Math.min(textW + 20, rect.x + rect.w - x);
    ctx.fillStyle = '#07c160';
    ctx.fillRect(x, y, labelW, labelH);
    ctx.fillStyle = '#ffffff';
