function encodeWords(words) {
  return words
    .map((item) => `${item.word}~${item.translation || ''}`)
    .join('|');
}

function pct(value) {
  return Math.round(value * 1000) / 10;
}

function decorateWords(words) {
  return (words || []).map((item) => {
    if (!item || !item.bbox) {
      return item;
    }
    const bbox = item.bbox;
    return Object.assign({}, item, {
      boxStyle: `left:${pct(bbox.x)}%;top:${pct(bbox.y)}%;width:${pct(bbox.w)}%;height:${pct(bbox.h)}%;`,
    });
  });
}

