parts.text:
Japanese TTS works (speaking false, no error, console clean). 

Now test the other languages at the cloud-function level to verify the prompts/voices. We can call `wx.cloud.callFunction` directly with the shapes image fileID and each lang, then compose and tts. This avoids navigating 6 times. We need a fileID for the shapes image in cloud storage. The index page uploaded the 256x256 image earlier; we can upload it again and use the fileID. Then for each lang:
- recognize(fileID, 'primary', lang)
- compose(words, 'primary', scene, lang)
- tts(sentence, lang)
Record the results.

Let me write a background chain:
```js
function(){
  globalThis.__multi = [];
  globalThis.__multiDone = false;
  var fs=wx.getFileSystemManager();
  var b64 = "..."; // shapes
  var p = wx.env.USER_DATA_PATH + '/multi.png';
  fs.writeFileSync(p, b64, 'base64');
  var langs = ['en','ja','ko','fr','es','de'];
  wx.cloud.uploadFile({cloudPath:'test/multi.png', filePath:p}).then(function(up){
    var i = 0;
    function next(){
      if (i >= langs.length) { globalThis.__multiDone = true; return; }
      var lang = langs[i++];
      wx.cloud.callFunction({name:'recognize', data:{fileID:up.fileID, level:'primary', lang:lang}}).then(function(r){
        var rec = r.result;
        if (!rec || !rec.ok) { globalThis.__multi.push({lang:lang, stage:'recognize', error:rec}); next(); return; }
        var words = (rec.data.words||[]).map(function(w){return w.word;});
        var scene = rec.data.scene;
        return wx.cloud.callFunction({name:'compose', data:{words:words, level:'primary', scene:scene, lang:lang}}).then(function(cr){
          var comp = cr.result;
          if (!comp || !comp.ok) { globalThis.__multi.push({lang:lang, stage:'compose', words:words, scene:scene, error:comp}); next(); return; }
          var sentence = comp.data.sentence;
          return wx.cloud.callFunction({name:'tts', data:{text:sentence, lang:lang}}).then(function(tr){
            var tts = tr.result;
            if (!tts || !tts.ok) { globalThis.__multi.push({lang:lang, stage:'tts', words:words, sentence:sentence, error:tts}); next(); return; }
            var path = wx.env.USER_DATA_PATH + '/multi-' + lang + '.mp3';
            fs.writeFileSync(path, tts.data.audioBase64, 'base64');
            globalThis.__multi.push({lang:lang, words:words, scene:scene, sentence:sentence, translation:comp.data.translation, audioSize:tts.data.size, path:path});
            next();
          });
        });
      }).catch(function(e){
        globalThis.__multi.push({lang:lang, error:(e.errMsg||e.message)});
        next();
      });
    }
    next();
  }).catch(function(e){ globalThis.__multi.push({error:(e.errMsg||e.message)}); globalThis.__multiDone=true; });
  return 'fired';
}
```
This runs 6 languages sequentially, each 3 calls. With thinking disabled, compose ~2s; recognize ~2-5s; tts ~2s. Total ~30-50s. Poll after 60s.

The shapes image is 256x256; recognize should return words in each language. If a language's words are not recognized, compose may fail. Let's see.

Let me run. The base64 is ~2KB, fine.

Note: The `tts` function now requires the `lang` parameter to choose the voice. We pass it. Good.

Let me run.

