display.text:
const cloud = require('wx-server-sdk');

cloud.init({ env: cloud.DYNAMIC_CURRENT_ENV });

exports.main = async () => {
  try {
    const res = await cloud.openapi.wxacode.getUnlimited({
      page: 'pages/index/index',
      scene: 'home',
      width: 280,
      checkPath: false,
    });

    if (!res || !res.buffer) {
      return {
        ok: false,
        error: { code: 'WXACODE_EMPTY', message: '小程序码为空' },
      };
    }

    return {
      ok: true,
      data: { codeBase64: res.buffer.toString('base64') },
    };
  } catch (err) {
    return {
      ok: false,
      error: {
        code: 'WXACODE_FAILED',
        message: (err && err.message) || '小程序码生成失败',
      },
    };
  }
};

