const { getLanguage } = require('../common/languages');

let audioContext = null;

function hashText(text) {
  let hash = 5381;
  for (let i = 0; i < text.length; i += 1) {
    hash = (((hash << 5) + hash) + text.charCodeAt(i)) >>> 0;
  }
  return hash.toString(16);
}

function getAudioContext() {
  if (!audioContext) {
    audioContext = wx.createInnerAudioContext();
    audioContext.onError((err) => {
      console.error('音频播放失败', err);
    });
  }
  return audioContext;
}

function play(filePath) {
  const context = getAudioContext();
  context.stop();
  context.src = filePath;
  context.play();
}

function getCachePath(text, opts) {
  const lang = opts.lang || 'en';
  const voice = opts.voice || getLanguage(lang).voice || '';
  const key = hashText(`${lang}|${voice}|${text}`);
  return `${wx.env.USER_DATA_PATH}/tts-${key}.mp3`;
}

function isUsableFile(filePath) {
  try {
    const stat = wx.getFileSystemManager().statSync(filePath);
    return stat.size > 0;
  } catch (err) {
    return false;
  }
}

function speak(text, options) {
  const opts = options || {};
  return new Promise((resolve, reject) => {
    if (!text) {
      reject(new Error('文本为空'));
      return;
    }

    const cachePath = getCachePath(text, opts);
    if (isUsableFile(cachePath)) {
      play(cachePath);
      resolve(cachePath);
      return;
    }

    if (!wx.cloud) {
      reject(new Error('云开发未初始化'));
      return;
    }

    const data = { text };
    if (opts.voice) {
      data.voice = opts.voice;
    }
    if (opts.lang) {
      data.lang = opts.lang;
    }

    wx.cloud
      .callFunction({ name: 'tts', data })
      .then((res) => {
        const result = res && res.result;
        if (!result || !result.ok) {
          const message = (result && result.error && result.error.message) || '语音合成失败';
          throw new Error(message);
        }
        const audio = result.data || {};
        if (!audio.audioBase64) {
          throw new Error('语音数据为空');
        }
        wx.getFileSystemManager().writeFileSync(cachePath, audio.audioBase64, 'base64');
        play(cachePath);
        resolve(cachePath);
      })
      .catch((err) => {
        reject(new Error((err && (err.message || err.errMsg)) || '语音合成失败'));
      });
  });
}

function stop() {
  if (audioContext) {
    audioContext.stop();
  }
}

module.exports = {
  speak,
  stop,
};

const KEY = 'history';
const MAX = 10;
const DIR = `${wx.env.USER_DATA_PATH}/history`;

function getFs() {
  return wx.getFileSystemManager();
}

function ensureDir() {
  try {
    getFs().accessSync(DIR);
  } catch (err) {
    try {
      getFs().mkdirSync(DIR, true);
    } catch (e) {
      // 目录已存在或无权限时忽略，后续复制会走降级
    }
  }
}

function load() {
  const list = wx.getStorageSync(KEY);
  return Array.isArray(list) ? list : [];
}

function removeImage(record) {
  if (!record || !record.imagePath) {
    return;
  }
  if (record.imagePath.indexOf(DIR) !== 0) {
    return;
  }
  try {
    getFs().unlinkSync(record.imagePath);
  } catch (err) {
    // 文件可能已不存在
  }
}

function save(record) {
  if (!record || !record.id) {
    return null;
  }

  ensureDir();
  const list = load();
  const index = list.findIndex((item) => item.id === record.id);
  let imagePath = record.imagePath || '';

  if (imagePath && imagePath.indexOf(DIR) !== 0) {
    const dest = `${DIR}/${record.id}.jpg`;
    try {
      getFs().copyFileSync(imagePath, dest);
      imagePath = dest;
    } catch (err) {
      imagePath = record.imagePath;
    }
  }

  const item = Object.assign({}, record, {
    imagePath,
    createdAt: record.createdAt || Date.now(),
    updatedAt: Date.now(),
  });

  item.words = (item.words || []).map((word) => {
    const copy = Object.assign({}, word);
    delete copy.boxStyle;
    return copy;
  });

  if (index !== -1) {
    list.splice(index, 1);
  }
  list.unshift(item);

  while (list.length > MAX) {
    removeImage(list.pop());
  }

  wx.setStorageSync(KEY, list);
  return item;
}

function update(id, patch) {
  if (!id) {
    return null;
  }
  const list = load();
  const index = list.findIndex((item) => item.id === id);
  if (index === -1) {
    return null;
  }
  list[index] = Object.assign({}, list[index], patch, { updatedAt: Date.now() });
  wx.setStorageSync(KEY, list);
  return list[index];
}

function createId() {
  return `${Date.now().toString(36)}${Math.random().toString(36).slice(2, 8)}`;
}

module.exports = {
  load,
  save,
  update,
  createId,
  MAX,
};

const KEY = 'wordbook';

function load() {
  const list = wx.getStorageSync(KEY);
  return Array.isArray(list) ? list : [];
}

function makeId(lang, word) {
  return `${lang || 'en'}:${String(word || '').toLowerCase()}`;
}

function isSaved(word, lang) {
  const id = makeId(lang, word);
  return load().some((item) => item.id === id);
}

function add(entry, lang) {
  const id = makeId(lang, entry.word);
  const list = load();
  if (list.some((item) => item.id === id)) {
    return true;
  }
  list.unshift({
    id,
    word: entry.word,
    translation: entry.translation || '',
    category: entry.category || '其他',
    lang: lang || 'en',
    level: entry.level || '',
    addedAt: Date.now(),
  });
  wx.setStorageSync(KEY, list);
  return true;
}

function remove(id) {
  const list = load().filter((item) => item.id !== id);
  wx.setStorageSync(KEY, list);
}

function toggle(entry, lang) {
  const id = makeId(lang, entry.word);
  const list = load();
  const index = list.findIndex((item) => item.id === id);
  if (index !== -1) {
    list.splice(index, 1);
    wx.setStorageSync(KEY, list);
    return false;
  }
  add(entry, lang);
  return true;
}

module.exports = {
  load,
  isSaved,
  add,
  remove,
  toggle,
  makeId,
};

