const { getLanguage } = require('../../common/languages');
const history = require('../../utils/history');

function formatDate(timestamp) {
  const date = new Date(timestamp || Date.now());
  const pad = (value) => (value < 10 ? `0${value}` : `${value}`);
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())} ${pad(date.getHours())}:${pad(date.getMinutes())}`;
}

Page({
  data: {
    items: [],
  },

  onShow() {
    this.load();
  },

  load() {
    const items = history.load().map((item) => {
      const language = getLanguage(item.lang);
      return Object.assign({}, item, {
        langName: language.name,
        dateText: formatDate(item.createdAt),
        wordText: (item.words || []).map((word) => word.word).join('、'),
      });
    });
    this.setData({ items });
  },

  openRecord(e) {
    const id = e.currentTarget.dataset.id;
    const item = history.load().find((record) => record.id === id);
    if (!item) {
      return;
    }
    wx.setStorageSync('pendingResult', Object.assign({}, item, { fromHistory: true }));
    wx.navigateTo({ url: '/pages/result/result' });
  },
});

.empty {
  padding: 120rpx 0;
  color: #a8adb5;
  font-size: 28rpx;
  text-align: center;
}

.record {
  display: flex;
  margin-bottom: 24rpx;
  padding: 20rpx;
  border-radius: 20rpx;
  background: #ffffff;
}

.thumb {
  width: 160rpx;
  height: 160rpx;
  margin-right: 24rpx;
  border-radius: 12rpx;
  background: #eef0f3;
  flex-shrink: 0;
}

.record-body {
  flex: 1;
  min-width: 0;
}

.record-meta {
  color: #8a9099;
  font-size: 24rpx;
}

.record-sentence {
  margin-top: 12rpx;
  color: #1f2329;
  font-size: 28rpx;
  line-height: 1.5;
  word-break: break-all;
}

{
  "navigationBarTitleText": "识别记录"
}

